//! Source signed Agent Runtime Envelope: closed snapshot, body binding, atomic nonce consumption.
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use hmac::{Hmac,Mac};
use base64::Engine;
use std::{collections::{BTreeSet,VecDeque},sync::{Arc,Mutex},time::{SystemTime,UNIX_EPOCH}};
#[derive(Clone,Debug,PartialEq,Eq)]pub struct EnvelopeError(pub &'static str);
impl std::fmt::Display for EnvelopeError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.write_str(self.0)}}impl std::error::Error for EnvelopeError{}
type Result<T>=std::result::Result<T,EnvelopeError>;
fn need(ok:bool,code:&'static str)->Result<()>{if ok{Ok(())}else{Err(EnvelopeError(code))}}
fn nonempty(v:&Value,code:&'static str)->Result<()>{need(v.as_str().is_some_and(|s|!s.trim().is_empty()),code)}
fn optional(v:&Value,code:&'static str)->Result<()>{if v.is_null(){Ok(())}else{nonempty(v,code)}}
fn closed(v:&Value,keys:&[&str],code:&'static str)->Result<()>{need(v.as_object().is_some_and(|m|m.len()==keys.len()&&keys.iter().all(|k|m.contains_key(*k))),code)}
fn one(v:&Value,values:&[&str])->bool{v.as_str().is_some_and(|s|values.contains(&s))}
fn now()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis().min(i64::MAX as u128)as i64}
pub fn canonical_runtime_json(v:&Value)->String{ai_platform_gateway_foundation::python_json::python_json(v,false,false)}
pub fn runtime_sha256(v:&Value)->String{format!("sha256:{:x}",Sha256::digest(canonical_runtime_json(v).as_bytes()))}
pub fn agent_memory_principal(caller:&str,agent:&str,version:&str)->String{let h=format!("{:x}",Sha256::digest(format!("{caller}:{agent}:{version}").as_bytes()));format!("am_{}",&h[..61])}
const CHANNELS:&[&str]=&["preview","hosted","embed","api","builtin"];
const SNAPSHOT:&[&str]=&["schema_version","tenant_id","agent_id","agent_version_id","publication","model","instructions","capabilities","knowledge","memory","channel_policy","fingerprints"];
const ENVELOPE:&[&str]=&["schema_version","issuer","tenant_id","caller_principal","agent_id","agent_version_id","draft_revision","publication_id","channel","session_id","resolved_snapshot","request_body_hash","snapshot_hash","spec_hash","issued_at_ms","expires_at_ms","nonce"];
fn reject_secrets(v:&Value)->Result<()>{match v{Value::Object(m)=>for(k,v)in m{let key=k.to_lowercase().chars().filter(|c|c.is_ascii_alphanumeric()).collect::<String>();need(!["apikey","apitoken","authorization","bearertoken","clientsecret","credential","credentialref","password","privatekey","refreshtoken","secret","secretref","tokenhash","tokenref"].contains(&key.as_str()),"AGENT_RUNTIME_SECRET_FORBIDDEN")?;reject_secrets(v)?},Value::Array(a)=>for v in a{reject_secrets(v)?},_=>{}}Ok(())}
pub fn validate_snapshot(s:&Value)->Result<()>{let code="AGENT_RUNTIME_SNAPSHOT_INVALID";closed(s,SNAPSHOT,code)?;need(s["schema_version"]=="agent-runtime/v1","AGENT_RUNTIME_SNAPSHOT_VERSION_UNSUPPORTED")?;nonempty(&s["tenant_id"],code)?;nonempty(&s["agent_id"],code)?;optional(&s["agent_version_id"],code)?;
 let p=&s["publication"];closed(p,&["id","channel","auth_mode"],code)?;optional(&p["id"],code)?;need(one(&p["channel"],CHANNELS)&&one(&p["auth_mode"],&["private","tenant","public","token"]),code)?;
 let m=&s["model"];closed(m,&["id","provider","parameters"],code)?;nonempty(&m["id"],code)?;nonempty(&m["provider"],code)?;need(m["parameters"].is_object(),code)?;
 let i=&s["instructions"];closed(i,&["agent","prompt_hash"],code)?;need(i["agent"].is_string(),code)?;nonempty(&i["prompt_hash"],code)?;
 let capabilities=s["capabilities"].as_array().ok_or(EnvelopeError(code))?;let mut ids=BTreeSet::new();for c in capabilities{closed(c,&["type","id","version","schema_hash","risk","config"],code)?;need(one(&c["type"],&["platform","mcp","skill","connector"])&&one(&c["risk"],&["low","medium","high","critical"]),code)?;nonempty(&c["id"],code)?;need(ids.insert(c["id"].as_str().unwrap()),code)?;optional(&c["version"],code)?;optional(&c["schema_hash"],code)?;need(c["config"].is_object(),code)?}
 let k=&s["knowledge"];closed(k,&["datasets","retrieval"],code)?;need(k["datasets"].as_array().is_some_and(|a|a.iter().all(|v|v.as_str().is_some_and(|s|!s.is_empty())))&&k["retrieval"].is_object(),code)?;
 closed(&s["memory"],&["mode"],code)?;need(one(&s["memory"]["mode"],&["off","session","user"]),code)?;
 let p=&s["channel_policy"];closed(p,&["attachments","high_risk_tools","allowed_origins"],code)?;need(p["attachments"].is_boolean()&&p["high_risk_tools"].is_boolean()&&p["allowed_origins"].as_array().is_some_and(|a|a.iter().all(Value::is_string)),code)?;
 closed(&s["fingerprints"],&["spec","tool_schema","skills","knowledge_revision"],code)?;for v in s["fingerprints"].as_object().unwrap().values(){nonempty(v,code)?}reject_secrets(s)
}
pub trait ReplayStore:Send+Sync{fn seen_or_record(&self,request_id:&str,ttl_ms:i64)->std::result::Result<bool,String>;}
pub struct InMemoryReplayStore{seen:Mutex<VecDeque<(String,i64)>>,capacity:usize}
impl Default for InMemoryReplayStore{fn default()->Self{Self::new(10000)}}impl InMemoryReplayStore{pub fn new(capacity:usize)->Self{Self{seen:Mutex::new(VecDeque::new()),capacity}}}
impl ReplayStore for InMemoryReplayStore{fn seen_or_record(&self,id:&str,ttl:i64)->std::result::Result<bool,String>{let time=now();let mut seen=self.seen.lock().map_err(|_|"replay lock unavailable")?;while seen.front().is_some_and(|(_,expiry)|*expiry<=time){seen.pop_front();}if seen.iter().any(|(key,expiry)|key==id&&*expiry>time){return Ok(true)}seen.retain(|(key,_)|key!=id);seen.push_back((id.into(),time.saturating_add(ttl)));while seen.len()>self.capacity{seen.pop_front();}Ok(false)}}
#[derive(Clone,Debug)]pub struct VerifiedAgentRuntime{pub tenant_id:String,pub caller_principal:String,pub agent_id:String,pub agent_version_id:Value,pub draft_revision:Value,pub publication_id:Value,pub channel:String,pub session_id:String,pub runtime_fingerprint:String,pub spec_hash:String,pub capability_ids:BTreeSet<String>,pub resolved_snapshot:Value}
impl VerifiedAgentRuntime{pub fn dimensions(&self)->Value{json!({"agent_id":self.agent_id,"agent_version_id":self.agent_version_id,"agent_draft_revision":self.draft_revision,"publication_id":self.publication_id,"channel":self.channel,"runtime_fingerprint":self.runtime_fingerprint,"agent_spec_hash":self.spec_hash})}}
pub struct AgentRuntimeSigner{secret:String,pub issuer:String,pub replay_store:Arc<dyn ReplayStore>,pub max_ttl_ms:i64,pub max_clock_skew_ms:i64}
impl AgentRuntimeSigner{
 pub fn new(secret:String,issuer:String,replay_store:Option<Arc<dyn ReplayStore>>,max_ttl_ms:i64,max_clock_skew_ms:i64)->Result<Self>{need(secret.chars().count()>=16||super::lease_authority::signing_enabled().map_err(|_|EnvelopeError("AGENT_RUNTIME_SIGNATURE_INVALID"))?,"Agent Runtime signing secret must be at least 16 chars")?;need(!issuer.is_empty()&&!issuer.contains(':'),"Agent Runtime issuer must be non-empty and colon-free")?;need(max_ttl_ms>0&&max_clock_skew_ms>=0,"Agent Runtime time bounds must be positive")?;Ok(Self{secret,issuer,replay_store:replay_store.unwrap_or_else(||Arc::new(InMemoryReplayStore::default())),max_ttl_ms,max_clock_skew_ms})}
 fn signature(&self,envelope:&Value)->String{let mut value=envelope.clone();value.as_object_mut().unwrap().remove("signature");let mut mac=Hmac::<Sha256>::new_from_slice(self.secret.as_bytes()).expect("HMAC arbitrary key");mac.update(canonical_runtime_json(&value).as_bytes());format!("sha256:{}",mac.finalize().into_bytes().iter().map(|b|format!("{b:02x}")).collect::<String>())}
 fn validate_unsigned(&self,e:&Value,time:i64)->Result<()>{let code="AGENT_RUNTIME_ENVELOPE_INVALID";closed(e,ENVELOPE,code)?;need(e["schema_version"]=="agent-runtime-envelope/v1","AGENT_RUNTIME_ENVELOPE_VERSION_UNSUPPORTED")?;for key in ["issuer","tenant_id","caller_principal","agent_id","session_id","spec_hash","nonce"]{nonempty(&e[key],code)?}optional(&e["agent_version_id"],code)?;optional(&e["publication_id"],code)?;need(one(&e["channel"],CHANNELS),code)?;need(e["draft_revision"].is_null()||e["draft_revision"].as_i64().is_some_and(|n|n>=1),code)?;
 let draft=!e["draft_revision"].is_null();let version=!e["agent_version_id"].is_null();let publication=!e["publication_id"].is_null();need(match e["channel"].as_str().unwrap(){"preview"=>draft!=version&&!publication,"builtin"=>!draft&&!version&&!publication,_=>!draft&&version&&publication},code)?;
 let issued=e["issued_at_ms"].as_i64().ok_or(EnvelopeError(code))?;let expires=e["expires_at_ms"].as_i64().ok_or(EnvelopeError(code))?;need(expires>issued&&expires.saturating_sub(issued)<=self.max_ttl_ms,"AGENT_RUNTIME_TTL_INVALID")?;need(time>=issued.saturating_sub(self.max_clock_skew_ms),"AGENT_RUNTIME_NOT_YET_VALID")?;need(time<=expires,"AGENT_RUNTIME_EXPIRED")?;nonempty(&e["request_body_hash"],code)?;nonempty(&e["snapshot_hash"],code)?;validate_snapshot(&e["resolved_snapshot"])
 }
 /// Identity includes the source keyword fields; time and nonce may be supplied by deterministic tests.
 pub fn sign(&self,identity:&Value,snapshot:&Value,body:&Value,issued:Option<i64>,expires:Option<i64>,nonce:Option<&str>)->Result<Value>{validate_snapshot(snapshot)?;let issued=issued.unwrap_or_else(now);let mut e=identity.clone();need(e.is_object(),"AGENT_RUNTIME_IDENTITY_INVALID")?;for key in ["tenant_id","caller_principal","agent_id","session_id","spec_hash"]{nonempty(&e[key],"AGENT_RUNTIME_IDENTITY_INVALID")?}for key in ["agent_version_id","publication_id"]{optional(&e[key],"AGENT_RUNTIME_IDENTITY_INVALID")?}let nonce=match nonce.filter(|s|!s.is_empty()){Some(n)=>n.into(),None=>{let mut bytes=[0u8;24];getrandom::fill(&mut bytes).map_err(|_|EnvelopeError("AGENT_RUNTIME_NONCE_UNAVAILABLE"))?;base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)}};
 e["schema_version"]=json!("agent-runtime-envelope/v1");e["issuer"]=json!(self.issuer);e["resolved_snapshot"]=snapshot.clone();e["request_body_hash"]=json!(runtime_sha256(body));e["snapshot_hash"]=json!(runtime_sha256(snapshot));e["issued_at_ms"]=json!(issued);e["expires_at_ms"]=json!(expires.unwrap_or(issued.saturating_add(30000)));e["nonce"]=json!(nonce);self.validate_unsigned(&e,issued)?;e["signature"]=json!(super::lease_authority::sign_claims("runtime-launch",&e).map_err(|_|EnvelopeError("AGENT_RUNTIME_SIGNATURE_INVALID"))?.unwrap_or_else(||self.signature(&e)));Ok(e)}
 pub fn verify(&self,envelope:&Value,body:&Value,tenant:&str,caller:&str,session:&str,time:Option<i64>)->Result<VerifiedAgentRuntime>{let code="AGENT_RUNTIME_ENVELOPE_INVALID";let mut keys=ENVELOPE.to_vec();keys.push("signature");closed(envelope,&keys,code)?;let mut e=envelope.clone();e.as_object_mut().unwrap().remove("signature");let time=time.unwrap_or_else(now);self.validate_unsigned(&e,time)?;
 fn same(a:&str,b:&str)->bool{a.len()==b.len()&&a.bytes().zip(b.bytes()).fold(0u8,|x,(a,b)|x|(a^b))==0}
 need(same(&runtime_sha256(&e["resolved_snapshot"]),e["snapshot_hash"].as_str().unwrap_or("")),"AGENT_RUNTIME_SNAPSHOT_HASH_MISMATCH")?;need(same(&runtime_sha256(body),e["request_body_hash"].as_str().unwrap_or("")),"AGENT_RUNTIME_BODY_HASH_MISMATCH")?;let signature=envelope["signature"].as_str().unwrap_or("");if signature.starts_with(super::lease_authority::wire::ENVELOPE_PREFIX){super::lease_authority::verify_claims("runtime-launch",signature,&e,time.max(0)as u64).map_err(|_|EnvelopeError("AGENT_RUNTIME_SIGNATURE_INVALID"))?;}else{need(super::lease_authority::legacy_admitted(time.max(0)as u64)&&same(signature,&self.signature(&e)),"AGENT_RUNTIME_SIGNATURE_INVALID")?;}
 for (field,expected,error) in [("issuer",self.issuer.as_str(),"AGENT_RUNTIME_ISSUER_INVALID"),("tenant_id",tenant,"AGENT_RUNTIME_TENANT_MISMATCH"),("caller_principal",caller,"AGENT_RUNTIME_CALLER_MISMATCH"),("session_id",session,"AGENT_RUNTIME_SESSION_MISMATCH")]{need(e[field]==expected,error)?}
 let s=&e["resolved_snapshot"];need(["tenant_id","agent_id","agent_version_id"].iter().all(|k|s[*k]==e[*k])&&s["publication"]["id"]==e["publication_id"]&&s["publication"]["channel"]==e["channel"]&&s["fingerprints"]["spec"]==e["spec_hash"],"AGENT_RUNTIME_IDENTITY_MISMATCH")?;
 let ttl=e["expires_at_ms"].as_i64().unwrap().saturating_sub(time).saturating_add(self.max_clock_skew_ms).max(1);let replay_key=format!("{}:{}:{}",e["issuer"].as_str().unwrap(),tenant,e["nonce"].as_str().unwrap());let replayed=self.replay_store.seen_or_record(&replay_key,ttl).map_err(|_|EnvelopeError("AGENT_RUNTIME_REPLAY_STORE_UNAVAILABLE"))?;need(!replayed,"AGENT_RUNTIME_REPLAYED")?;
 Ok(VerifiedAgentRuntime{tenant_id:tenant.into(),caller_principal:caller.into(),agent_id:e["agent_id"].as_str().unwrap().into(),agent_version_id:e["agent_version_id"].clone(),draft_revision:e["draft_revision"].clone(),publication_id:e["publication_id"].clone(),channel:e["channel"].as_str().unwrap().into(),session_id:session.into(),runtime_fingerprint:e["snapshot_hash"].as_str().unwrap().into(),spec_hash:e["spec_hash"].as_str().unwrap().into(),capability_ids:s["capabilities"].as_array().unwrap().iter().map(|c|c["id"].as_str().unwrap().into()).collect(),resolved_snapshot:s.clone()})
 }
}
